/**
 * components/StockSelector.js
 * Stock dropdown + quick-pick cards + Predict button
 */

import React from 'react';
import './StockSelector.css';

const QUICK = [
  { ticker: 'AAPL', price: 214.35, change: +1.24 },
  { ticker: 'MSFT', price: 415.82, change: -0.87 },
  { ticker: 'NVDA', price: 132.45, change: +3.21 },
];

export default function StockSelector({ stocks, selected, onSelect, onPredict, loading }) {
  return (
    <div className="sel-row">

      {/* DROPDOWN */}
      <div className="sel-card">
        <div className="sel-lbl">Select Stock</div>
        <div className="sel-wrap">
          <select
            className="stk-select"
            value={selected}
            onChange={e => onSelect(e.target.value)}
            disabled={loading}
          >
            {stocks.map(s => (
              <option key={s.ticker} value={s.ticker}>
                {s.ticker} — {s.name}
              </option>
            ))}
          </select>
        </div>
      </div>

      {/* QUICK PICKS */}
      {QUICK.map(q => (
        <div
          key={q.ticker}
          className={`quick-card ${selected === q.ticker ? 'active' : ''}`}
          onClick={() => !loading && onSelect(q.ticker)}
          role="button"
          tabIndex={0}
          onKeyDown={e => e.key === 'Enter' && !loading && onSelect(q.ticker)}
        >
          <div className="qc-ticker">{q.ticker}</div>
          <div className="qc-price">${q.price.toFixed(2)}</div>
          <div className={q.change >= 0 ? 'qc-up' : 'qc-dn'}>
            {q.change >= 0 ? '▲' : '▼'}{Math.abs(q.change).toFixed(2)}%
          </div>
        </div>
      ))}

      {/* PREDICT BUTTON */}
      <button className="pred-btn" onClick={onPredict} disabled={loading}>
        {loading
          ? <><span className="spin-sm" /><span>Analyzing…</span></>
          : <><span>⚡</span><span>PREDICT</span></>}
      </button>
    </div>
  );
}
